import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'webp']

def sanitize_filename(name):
    """Remove path traversal attempts but allow format specification"""
    name = name.replace('..', '').replace('/', '').replace('\\', '')
    return name

def get_image_dimensions(filepath):
    """Use identify command to get image dimensions"""
    cmd = f"identify -format '%wx%h' {filepath}"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=10)
    if result.returncode != 0:
        return None
    return result.stdout.strip()

def convert_image(input_path, output_format, resize=None):
    """Convert image to specified format using ImageMagick"""
    output_filename = f"converted_{os.urandom(8).hex()}.{output_format}"
    output_path = os.path.join(tempfile.gettempdir(), output_filename)

    cmd = f"convert {input_path}"
    if resize:
        cmd += f" -resize {resize}"
    cmd += f" {output_path}"

    result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=30)
    if result.returncode != 0:
        raise RuntimeError(f"Conversion failed: {result.stderr}")
    return output_path

@app.route('/api/image/convert', methods=['POST'])
def convert():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    output_format = request.form.get('format', 'png')
    resize = request.form.get('resize', None)

    if output_format not in ALLOWED_FORMATS:
        return jsonify({'error': f'Format must be one of: {ALLOWED_FORMATS}'}), 400

    # Validate resize parameter format (e.g., "800x600")
    if resize and not all(c.isdigit() or c == 'x' for c in resize):
        return jsonify({'error': 'Invalid resize format. Use WxH (e.g., 800x600)'}), 400

    # Save uploaded file
    input_filename = sanitize_filename(file.filename)
    input_path = os.path.join(tempfile.gettempdir(), f"upload_{os.urandom(8).hex()}_{input_filename}")
    file.save(input_path)

    try:
        dimensions = get_image_dimensions(input_path)
        output_path = convert_image(input_path, output_format, resize)

        return jsonify({
            'success': True,
            'original_dimensions': dimensions,
            'output': output_filename,
            'format': output_format
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/api/image/info', methods=['POST'])
def info():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    input_filename = sanitize_filename(file.filename)
    input_path = os.path.join(tempfile.gettempdir(), f"info_{os.urandom(8).hex()}_{input_filename}")
    file.save(input_path)

    try:
        dimensions = get_image_dimensions(input_path)
        # Get detailed info
        cmd = f"identify -verbose {input_path}"
        result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=10)

        return jsonify({
            'dimensions': dimensions,
            'details': result.stdout[:2000]
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
